1	//! Build script: compile Telegram channel WASM from source.
2	//!
3	//! Do not commit compiled WASM binaries — they are a supply chain risk.
4	//! This script builds telegram.wasm from channels-src/telegram before the main crate compiles.
5	//!
6	//! Reproducible build:
7	//!   cargo build --release
8	//! (build.rs invokes the channel build automatically)
9	//!
10	//! Prerequisites: rustup target add wasm32-wasip2, cargo install wasm-tools
11	
12	use std::env;
13	use std::path::{Path, PathBuf};
14	use std::process::Command;
15	
16	fn main() {
17	    let manifest_dir = env::var("CARGO_MANIFEST_DIR").unwrap();
18	    let root = PathBuf::from(&manifest_dir);
19	
20	    // ── Embed registry manifests ────────────────────────────────────────
21	    embed_registry_catalog(&root);
22	
23	    // ── Embed bundled skills ────────────────────────────────────────────
24	    embed_skills(&root);
25	
26	    // ── Build Telegram channel WASM ─────────────────────────────────────
27	    let channel_dir = root.join("channels-src/telegram");
28	    let wasm_out = channel_dir.join("telegram.wasm");
29	
30	    // Rerun when channel source or build script changes
31	    println!("cargo:rerun-if-changed=channels-src/telegram/src");
32	    println!("cargo:rerun-if-changed=channels-src/telegram/Cargo.toml");
33	    println!("cargo:rerun-if-changed=wit/channel.wit");
34	
35	    if !channel_dir.is_dir() {
36	        return;
37	    }
38	
39	    // Build WASM module
40	    let status = match Command::new("cargo")
41	        .args([
42	            "build",
43	            "--release",
44	            "--target",
45	            "wasm32-wasip2",
46	            "--manifest-path",
47	            channel_dir.join("Cargo.toml").to_str().unwrap(),
48	        ])
49	        .current_dir(&root)
50	        .status()
51	    {
52	        Ok(s) => s,
53	        Err(_) => {
54	            eprintln!(
55	                "cargo:warning=Telegram channel build failed. Run: ./channels-src/telegram/build.sh"
56	            );
57	            return;
58	        }
59	    };
60	
61	    if !status.success() {
62	        eprintln!(
63	            "cargo:warning=Telegram channel build failed. Run: ./channels-src/telegram/build.sh"
64	        );
65	        return;
66	    }
67	
68	    let raw_wasm = channel_dir.join("target/wasm32-wasip2/release/telegram_channel.wasm");
69	    if !raw_wasm.exists() {
70	        eprintln!(
71	            "cargo:warning=Telegram WASM output not found at {:?}",
72	            raw_wasm
73	        );
74	        return;
75	    }
76	
77	    // Convert to component and strip (wasm-tools)
78	    let component_ok = Command::new("wasm-tools")
79	        .args([
80	            "component",
81	            "new",
82	            raw_wasm.to_str().unwrap(),
83	            "-o",
84	            wasm_out.to_str().unwrap(),
85	        ])
86	        .current_dir(&root)
87	        .status()
88	        .map(|s| s.success())
89	        .unwrap_or(false);
90	
91	    if !component_ok {
92	        // Fallback: copy raw module if wasm-tools unavailable
93	        if std::fs::copy(&raw_wasm, &wasm_out).is_err() {
94	            eprintln!("cargo:warning=wasm-tools not found. Run: cargo install wasm-tools");
95	        }
96	    } else {
97	        // Strip debug info (use temp file to avoid clobbering)
98	        let stripped = wasm_out.with_extension("wasm.stripped");
99	        let strip_ok = Command::new("wasm-tools")
100	            .args([
101	                "strip",
102	                wasm_out.to_str().unwrap(),
103	                "-o",
104	                stripped.to_str().unwrap(),
105	            ])
106	            .current_dir(&root)
107	            .status()
108	            .map(|s| s.success())
109	            .unwrap_or(false);
110	        if strip_ok {
111	            let _ = std::fs::rename(&stripped, &wasm_out);
112	        }
113	    }
114	}
