116	/// Collect all registry manifests into a single JSON blob at compile time.
117	///
118	/// Output: `$OUT_DIR/embedded_catalog.json` with structure:
119	/// ```json
120	/// { "tools": [...], "channels": [...], "bundles": {...} }
121	/// ```
122	fn embed_registry_catalog(root: &Path) {
123	    use std::fs;
124	
125	    let registry_dir = root.join("registry");
126	
127	    // Rerun if the bundles file changes (per-file watches for tools/channels
128	    // are emitted inside collect_json_files to track content changes reliably).
129	    println!("cargo:rerun-if-changed=registry/_bundles.json");
130	
131	    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap());
132	    let out_path = out_dir.join("embedded_catalog.json");
133	
134	    if !registry_dir.is_dir() {
135	        // No registry dir: write empty catalog
136	        fs::write(
137	            &out_path,
138	            r#"{"tools":[],"channels":[],"mcp_servers":[],"bundles":{"bundles":{}}}"#,
139	        )
140	        .unwrap();
141	        return;
142	    }
143	
144	    let mut tools = Vec::new();
145	    let mut channels = Vec::new();
146	    let mut mcp_servers = Vec::new();
147	
148	    // Collect tool manifests
149	    let tools_dir = registry_dir.join("tools");
150	    if tools_dir.is_dir() {
151	        collect_json_files(&tools_dir, &mut tools);
152	    }
153	
154	    // Collect channel manifests
155	    let channels_dir = registry_dir.join("channels");
156	    if channels_dir.is_dir() {
157	        collect_json_files(&channels_dir, &mut channels);
158	    }
159	
160	    // Collect MCP server manifests
161	    let mcp_servers_dir = registry_dir.join("mcp-servers");
162	    if mcp_servers_dir.is_dir() {
163	        collect_json_files(&mcp_servers_dir, &mut mcp_servers);
164	    }
165	
166	    // Read bundles
167	    let bundles_path = registry_dir.join("_bundles.json");
168	    let bundles_raw = if bundles_path.is_file() {
169	        fs::read_to_string(&bundles_path).unwrap_or_else(|_| r#"{"bundles":{}}"#.to_string())
170	    } else {
171	        r#"{"bundles":{}}"#.to_string()
172	    };
173	
174	    // Build the combined JSON
175	    let catalog = format!(
176	        r#"{{"tools":[{}],"channels":[{}],"mcp_servers":[{}],"bundles":{}}}"#,
177	        tools.join(","),
178	        channels.join(","),
179	        mcp_servers.join(","),
180	        bundles_raw,
181	    );
182	
183	    fs::write(&out_path, catalog).unwrap();
184	}
185	
186	/// Collect all `skills/*/SKILL.md` files into an embedded JSON blob.
187	///
188	/// Output: `$OUT_DIR/embedded_skills.json` — a JSON array of `{"name": "...", "content": "..."}`.
189	/// These are loaded at runtime as bundled skills (lowest discovery priority, Trusted trust level).
190	fn embed_skills(root: &Path) {
191	    use std::fs;
192	
193	    let skills_dir = root.join("skills");
194	
195	    // Rerun when any skill changes
196	    println!("cargo:rerun-if-changed=skills");
197	
198	    let out_dir = PathBuf::from(env::var("OUT_DIR").unwrap()); // safety: build script panics on failure
199	    let out_path = out_dir.join("embedded_skills.json");
200	
201	    if !skills_dir.is_dir() {
202	        fs::write(&out_path, "[]").unwrap(); // safety: build script
203	        return;
204	    }
205	
206	    let mut skills: Vec<String> = Vec::new();
207	
208	    let mut entries: Vec<_> = fs::read_dir(&skills_dir)
209	        .unwrap() // safety: build script
210	        .filter_map(|e| e.ok())
211	        .filter(|e| e.path().is_dir())
212	        .collect();
213	    entries.sort_by_key(|e| e.file_name());
214	
215	    for entry in entries {
216	        let skill_md = entry.path().join("SKILL.md");
217	        if !skill_md.is_file() {
218	            continue;
219	        }
220	        // Emit per-file watch
221	        println!("cargo:rerun-if-changed={}", skill_md.display());
222	
223	        let name = entry.file_name().to_string_lossy().to_string();
224	        if let Ok(content) = fs::read_to_string(&skill_md) {
225	            // Escape for JSON embedding
226	            let name_json = serde_json::to_string(&name).unwrap(); // safety: build script
227	            let content_json = serde_json::to_string(&content).unwrap(); // safety: build script
228	            skills.push(format!(
229	                r#"{{"name":{},"content":{}}}"#,
230	                name_json, content_json
231	            ));
232	        }
233	    }
234	
235	    let catalog = format!("[{}]", skills.join(","));
236	    fs::write(&out_path, catalog).unwrap(); // safety: build script
237	}
238	
239	/// Read all .json files from a directory and push their raw contents into `out`.
240	fn collect_json_files(dir: &Path, out: &mut Vec<String>) {
241	    use std::fs;
242	
243	    let mut entries: Vec<_> = fs::read_dir(dir)
244	        .unwrap()
245	        .filter_map(|e| e.ok())
246	        .filter(|e| {
247	            e.path().is_file() && e.path().extension().and_then(|x| x.to_str()) == Some("json")
248	        })
249	        .collect();
250	
251	    // Sort for deterministic output
252	    entries.sort_by_key(|e| e.file_name());
253	
254	    for entry in entries {
255	        // Emit per-file watch so Cargo reruns when file contents change
256	        println!("cargo:rerun-if-changed={}", entry.path().display());
257	        if let Ok(content) = fs::read_to_string(entry.path()) {
258	            out.push(content);
259	        }
260	    }
261	}
