1	//! Generic WASM tool loader for loading tools from files or directories.
2	//!
3	//! This module provides a way to load WASM tools dynamically at runtime from:
4	//! - A directory containing `<name>.wasm` and `<name>.capabilities.json`
5	//! - Build artifacts in `tools-src/` (dev mode, auto-detected)
6	//! - Database storage (via [`WasmToolStore`])
7	//!
8	//! # Example: Loading from Directory
9	//!
10	//! ```text
11	//! ~/.ironclaw/tools/
12	//! ├── slack.wasm
13	//! ├── slack.capabilities.json
14	//! ├── github.wasm
15	//! └── github.capabilities.json
16	//! ```
17	//!
18	//! ```ignore
19	//! let loader = WasmToolLoader::new(runtime, registry);
20	//! loader.load_from_dir(Path::new("~/.ironclaw/tools/")).await?;
21	//! ```
22	//!
23	//! # Dev Mode
24	//!
25	//! When `load_dev_tools()` is called, the loader scans `tools-src/*/` for build
26	//! artifacts. Tools found there are loaded directly from the build output,
27	//! skipping the install directory. This means during development you just
28	//! rebuild the WASM and restart the host, no manual copy step needed.
29	//!
30	//! # Security
31	//!
32	//! Tools loaded from files are assigned `TrustLevel::User` by default, meaning
33	//! they run with the most restrictive permissions. Only tools explicitly marked
34	//! as `verified` or `system` in the database get elevated trust.
35	
36	use std::collections::HashMap;
37	use std::path::{Path, PathBuf};
38	use std::sync::Arc;
39	
40	use tokio::fs;
41	
42	use crate::secrets::SecretsStore;
43	use crate::tools::registry::{ToolRegistry, WasmRegistrationError, WasmToolRegistration};
44	use crate::tools::wasm::capabilities_schema::CapabilitiesFile;
45	use crate::tools::wasm::{
46	    Capabilities, OAuthRefreshConfig, WasmError, WasmStorageError, WasmToolRuntime, WasmToolStore,
47	};
48	
49	/// Error during WASM tool loading.
50	#[derive(Debug, thiserror::Error)]
51	pub enum WasmLoadError {
52	    #[error("IO error: {0}")]
53	    Io(#[from] std::io::Error),
54	
55	    #[error("WASM file not found: {0}")]
56	    WasmNotFound(PathBuf),
57	
58	    #[error("Capabilities file not found: {0}")]
59	    CapabilitiesNotFound(PathBuf),
60	
61	    #[error("Invalid capabilities JSON: {0}")]
62	    InvalidCapabilities(String),
63	
64	    #[error("WASM compilation error: {0}")]
65	    Compilation(#[from] WasmError),
66	
67	    #[error("Storage error: {0}")]
68	    Storage(#[from] WasmStorageError),
69	
70	    #[error("Registration error: {0}")]
71	    Registration(#[from] WasmRegistrationError),
72	
73	    #[error("Invalid tool name: {0}")]
74	    InvalidName(String),
75	
76	    #[error("WIT version mismatch: {0}")]
77	    WitVersionMismatch(String),
78	}
79	
80	/// Loads WASM tools from files or storage into the registry.
81	pub struct WasmToolLoader {
82	    runtime: Arc<WasmToolRuntime>,
83	    registry: Arc<ToolRegistry>,
84	    secrets_store: Option<Arc<dyn SecretsStore + Send + Sync>>,
85	}
86	
87	impl WasmToolLoader {
88	    /// Create a new loader with the given runtime and registry.
89	    pub fn new(runtime: Arc<WasmToolRuntime>, registry: Arc<ToolRegistry>) -> Self {
90	        Self {
91	            runtime,
92	            registry,
93	            secrets_store: None,
94	        }
95	    }
96	
97	    /// Set the secrets store for credential injection in WASM tools.
98	    pub fn with_secrets_store(mut self, store: Arc<dyn SecretsStore + Send + Sync>) -> Self {
99	        self.secrets_store = Some(store);
100	        self
101	    }
102	
103	    /// Load a single WASM tool from a file pair.
104	    ///
105	    /// Expects:
106	    /// - `wasm_path`: Path to the `.wasm` file
107	    /// - `capabilities_path`: Path to the `.capabilities.json` file (optional)
108	    ///
109	    /// If no capabilities file is provided, the tool gets no capabilities (default deny).
110	    pub async fn load_from_files(
111	        &self,
112	        name: &str,
113	        wasm_path: &Path,
114	        capabilities_path: Option<&Path>,
115	    ) -> Result<(), WasmLoadError> {
116	        if name.is_empty() || name.contains('/') || name.contains('\\') {
117	            return Err(WasmLoadError::InvalidName(name.to_string()));
118	        }
119	
120	        // Read WASM bytes
121	        if !wasm_path.exists() {
122	            return Err(WasmLoadError::WasmNotFound(wasm_path.to_path_buf()));
123	        }
124	        let wasm_bytes = fs::read(wasm_path).await?;
125	
126	        // Read capabilities (optional) and extract OAuth refresh config
127	        // and tool description. Parameter schema is auto-derived from the
128	        // WASM module's schema() export (see WasmToolSchemas::compact_schema).
129	        let (capabilities, oauth_refresh, description) = if let Some(cap_path) = capabilities_path {
130	            if cap_path.exists() {
131	                let cap_bytes = fs::read(cap_path).await?;
132	                let cap_file = CapabilitiesFile::from_bytes(&cap_bytes)
133	                    .map_err(|e| WasmLoadError::InvalidCapabilities(e.to_string()))?;
134	                cap_file.validate(name);
135	
136	                // Check WIT version compatibility
137	                check_wit_version_compat(
138	                    name,
139	                    cap_file.wit_version.as_deref(),
140	                    crate::tools::wasm::WIT_TOOL_VERSION,
141	                )?;
142	
143	                let caps = cap_file.to_capabilities();
144	                let oauth = resolve_oauth_refresh_config(&cap_file);
145	                let desc = cap_file.description.clone();
146	                if desc.is_none() {
147	                    tracing::warn!(
148	                        tool = name,
149	                        path = %cap_path.display(),
150	                        "Capabilities file missing \"description\" field; \
151	                         tool will use generic fallback description"
152	                    );
153	                }
154	                (caps, oauth, desc)
155	            } else {
156	                tracing::warn!(
157	                    tool = name,
158	                    path = %cap_path.display(),
159	                    "Capabilities file not found, using default (no permissions)"
160	                );
161	                (Capabilities::default(), None, None)
162	            }
163	        } else {
164	            tracing::warn!(
165	                tool = name,
166	                "No capabilities file for WASM tool; \
167	                     tool will use generic fallback description"
168	            );
169	            (Capabilities::default(), None, None)
170	        };
171	
172	        // Register the tool
173	        self.registry
174	            .register_wasm(WasmToolRegistration {
175	                name,
176	                wasm_bytes: &wasm_bytes,
177	                runtime: &self.runtime,
178	                capabilities,
179	                limits: None,
180	                description: description.as_deref(),
181	                schema: None,
182	                secrets_store: self.secrets_store.clone(),
183	                oauth_refresh,
184	            })
185	            .await?;
186	
187	        tracing::debug!(
188	            name = name,
189	            wasm_path = %wasm_path.display(),
190	            "Loaded WASM tool from file"
191	        );
192	
193	        Ok(())
194	    }
195	
196	    /// Load all WASM tools from a directory.
197	    ///
198	    /// Scans the directory for `*.wasm` files and loads each one, looking for
199	    /// a matching `*.capabilities.json` sidecar file.
200	    ///
201	    /// # Directory Layout
202	    ///
203	    /// ```text
204	    /// tools/
205	    /// ├── slack.wasm                  <- Tool WASM component
206	    /// ├── slack.capabilities.json     <- Capabilities (optional)
207	    /// ├── github.wasm
208	    /// └── github.capabilities.json
209	    /// ```
210	    ///
211	    /// Tools without a capabilities file get no permissions (default deny).
212	    pub async fn load_from_dir(&self, dir: &Path) -> Result<LoadResults, WasmLoadError> {
213	        match fs::metadata(dir).await {
214	            Ok(meta) if meta.is_dir() => {}
215	            Ok(_) => {
216	                return Err(WasmLoadError::Io(std::io::Error::new(
217	                    std::io::ErrorKind::NotADirectory,
218	                    format!("{} is not a directory", dir.display()),
219	                )));
220	            }
221	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
222	                return Ok(LoadResults::default());
223	            }
224	            Err(e) => return Err(WasmLoadError::Io(e)),
225	        }
226	
227	        // Handle TOCTOU: if read_dir fails with NotFound, treat as empty
228	        let mut entries = match fs::read_dir(dir).await {
229	            Ok(entries) => entries,
230	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
231	                return Ok(LoadResults::default());
232	            }
233	            Err(e) => return Err(WasmLoadError::Io(e)),
234	        };
235	
236	        let mut results = LoadResults::default();
237	        let mut tool_entries = Vec::new();
238	
239	        while let Some(entry) = entries.next_entry().await? {
240	            let path = entry.path();
241	
242	            if path.extension().and_then(|e| e.to_str()) != Some("wasm") {
243	                continue;
244	            }
245	
246	            let name = match path.file_stem().and_then(|s| s.to_str()) {
247	                Some(n) => n.to_string(),
248	                None => {
249	                    results.errors.push((
250	                        path.clone(),
251	                        WasmLoadError::InvalidName("invalid filename".to_string()),
252	                    ));
253	                    continue;
254	                }
255	            };
256	
257	            let cap_path = path.with_extension("capabilities.json");
258	            let has_cap = cap_path.exists();
259	            tool_entries.push((name, path, if has_cap { Some(cap_path) } else { None }));
260	        }
261	
262	        // Load all tools in parallel (file I/O + WASM compilation + registration)
263	        let load_futures = tool_entries
264	            .iter()
265	            .map(|(name, path, cap_path)| self.load_from_files(name, path, cap_path.as_deref()));
266	
267	        let load_results = futures::future::join_all(load_futures).await;
268	
269	        for ((name, path, _), result) in tool_entries.into_iter().zip(load_results) {
270	            match result {
271	                Ok(()) => {
272	                    results.loaded.push(name);
273	                }
274	                Err(e) => {
275	                    tracing::error!(
276	                        name = name,
277	                        path = %path.display(),
278	                        error = %e,
279	                        "Failed to load WASM tool"
280	                    );
281	                    results.errors.push((path, e));
282	                }
283	            }
284	        }
285	
286	        if !results.loaded.is_empty() {
287	            tracing::debug!(
288	                count = results.loaded.len(),
289	                tools = ?results.loaded,
290	                "Loaded WASM tools from directory"
291	            );
292	        }
293	
294	        Ok(results)
295	    }
296	
297	    /// Load a WASM tool from database storage.
298	    ///
299	    /// This is a convenience wrapper around [`ToolRegistry::register_wasm_from_storage`].
300	    pub async fn load_from_storage(
301	        &self,
302	        store: &dyn WasmToolStore,
303	        user_id: &str,
304	        tool_name: &str,
305	    ) -> Result<(), WasmLoadError> {
306	        self.registry
307	            .register_wasm_from_storage(store, &self.runtime, user_id, tool_name)
308	            .await?;
309	
310	        tracing::info!(
311	            user_id = user_id,
312	            name = tool_name,
313	            "Loaded WASM tool from storage"
314	        );
315	
316	        Ok(())
317	    }
318	
319	    /// Load all active WASM tools for a user from storage.
320	    pub async fn load_all_from_storage(
321	        &self,
322	        store: &dyn WasmToolStore,
323	        user_id: &str,
324	    ) -> Result<LoadResults, WasmLoadError> {
325	        let tools = store.list(user_id).await?;
326	        let mut results = LoadResults::default();
327	
328	        for tool in tools {
329	            // Skip non-active tools
330	            if tool.status != crate::tools::wasm::ToolStatus::Active {
331	                continue;
332	            }
333	
334	            match self.load_from_storage(store, user_id, &tool.name).await {
335	                Ok(()) => {
336	                    results.loaded.push(tool.name);
337	                }
338	                Err(e) => {
339	                    tracing::error!(
340	                        name = tool.name,
341	                        user_id = user_id,
342	                        error = %e,
343	                        "Failed to load WASM tool from storage"
344	                    );
345	                    results.errors.push((PathBuf::from(&tool.name), e));
346	                }
347	            }
348	        }
349	
350	        Ok(results)
351	    }
352	}
353	
354	/// Check that a declared WIT version is compatible with the host WIT version.
355	///
356	/// Compatibility rules (semver):
357	/// - Same major version required (0.x is special: same minor required)
358	/// - Extension WIT version must not be greater than host version
359	///
360	/// If `declared` is `None`, the check is skipped (pre-versioning extension).
361	pub fn check_wit_version_compat(
362	    name: &str,
363	    declared: Option<&str>,
364	    host_version: &str,
365	) -> Result<(), WasmLoadError> {
366	    let Some(declared_str) = declared else {
367	        return Ok(());
368	    };
369	
370	    let declared = semver::Version::parse(declared_str).map_err(|e| {
371	        WasmLoadError::WitVersionMismatch(format!(
372	            "Extension '{name}' has invalid wit_version '{declared_str}': {e}"
373	        ))
374	    })?;
375	
376	    let host = semver::Version::parse(host_version).map_err(|e| {
377	        WasmLoadError::WitVersionMismatch(format!(
378	            "Host WIT version '{host_version}' is invalid: {e}"
379	        ))
380	    })?;
381	
382	    // Major version must match
383	    if declared.major != host.major {
384	        return Err(WasmLoadError::WitVersionMismatch(format!(
385	            "Extension '{name}' compiled against WIT {declared}, but host supports WIT {host}. \
386	             Major version mismatch — rebuild the extension."
387	        )));
388	    }
389	
390	    // For 0.x versions, minor must also match (semver: 0.x.y has no compatibility guarantees)
391	    if declared.major == 0 && declared.minor != host.minor {
392	        return Err(WasmLoadError::WitVersionMismatch(format!(
393	            "Extension '{name}' compiled against WIT {declared}, but host supports WIT {host}. \
394	             Rebuild the extension against the current WIT."
395	        )));
396	    }
397	
398	    // Extension cannot be newer than host
399	    if declared > host {
400	        return Err(WasmLoadError::WitVersionMismatch(format!(
401	            "Extension '{name}' compiled against WIT {declared}, but host only supports WIT {host}. \
402	             Update the host or rebuild with an older WIT."
403	        )));
404	    }
405	
406	    Ok(())
407	}
