734	
735	    impl Drop for EnvVarGuard {
736	        fn drop(&mut self) {
737	            // SAFETY: Tests use lock_env() to serialize environment access.
738	            unsafe {
739	                if let Some(ref value) = self.previous {
740	                    std::env::set_var(&self.key, value);
