749	        let previous = std::env::var(key).ok();
750	        // SAFETY: Tests use lock_env() to serialize environment access.
751	        unsafe {
752	            match value {
753	                Some(value) => std::env::set_var(key, value),
754	                None => std::env::remove_var(key),
755	            }
756	        }
757	        EnvVarGuard {
758	            key: key.to_string(),
759	            previous,
760	        }
761	    }
