31	/// Load WASM channels and register their webhook routes.
32	pub async fn setup_wasm_channels(
33	    config: &Config,
34	    secrets_store: &Option<Arc<dyn SecretsStore + Send + Sync>>,
35	    extension_manager: Option<&Arc<ExtensionManager>>,
36	    database: Option<&Arc<dyn Database>>,
37	) -> Option<WasmChannelSetup> {
38	    let runtime = match WasmChannelRuntime::new(WasmChannelRuntimeConfig::default()) {
39	        Ok(r) => Arc::new(r),
40	        Err(e) => {
41	            tracing::warn!("Failed to initialize WASM channel runtime: {}", e);
42	            return None;
43	        }
44	    };
45	
46	    let pairing_store = Arc::new(PairingStore::new());
47	    let settings_store: Option<Arc<dyn crate::db::SettingsStore>> =
48	        database.map(|db| Arc::clone(db) as Arc<dyn crate::db::SettingsStore>);
49	    let mut loader = WasmChannelLoader::new(
50	        Arc::clone(&runtime),
51	        Arc::clone(&pairing_store),
52	        settings_store.clone(),
53	        config.owner_id.clone(),
54	    );
55	    if let Some(secrets) = secrets_store {
56	        loader = loader.with_secrets_store(Arc::clone(secrets));
57	    }
58	
59	    let results = match loader
60	        .load_from_dir(&config.channels.wasm_channels_dir)
61	        .await
62	    {
63	        Ok(r) => r,
64	        Err(e) => {
65	            tracing::warn!("Failed to scan WASM channels directory: {}", e);
66	            return None;
67	        }
68	    };
69	
70	    let wasm_router = Arc::new(WasmChannelRouter::new());
71	    let mut channels: Vec<(String, Box<dyn crate::channels::Channel>)> = Vec::new();
72	    let mut channel_names: Vec<String> = Vec::new();
73	
74	    for loaded in results.loaded {
75	        let (name, channel) = register_channel(
76	            loaded,
77	            config,
78	            secrets_store,
79	            settings_store.as_ref(),
80	            &wasm_router,
81	        )
82	        .await;
83	        channel_names.push(name.clone());
84	        channels.push((name, channel));
85	    }
86	
87	    for (path, err) in &results.errors {
88	        tracing::warn!("Failed to load WASM channel {}: {}", path.display(), err);
89	    }
90	
91	    // Always create webhook routes (even with no channels loaded) so that
92	    // channels hot-added at runtime can receive webhooks without a restart.
93	    let webhook_routes = {
94	        Some(create_wasm_channel_router(
95	            Arc::clone(&wasm_router),
96	            extension_manager.map(Arc::clone),
97	        ))
98	    };
99	
100	    Some(WasmChannelSetup {
101	        channels,
102	        channel_names,
103	        webhook_routes,
104	        wasm_channel_runtime: runtime,
105	        pairing_store,
106	        wasm_channel_router: wasm_router,
107	    })
108	}
