110	/// Process a single loaded WASM channel: retrieve secrets, inject config,
111	/// register with the router, and set up signing keys and credentials.
112	async fn register_channel(
113	    loaded: LoadedChannel,
114	    config: &Config,
115	    secrets_store: &Option<Arc<dyn SecretsStore + Send + Sync>>,
116	    settings_store: Option<&Arc<dyn crate::db::SettingsStore>>,
117	    wasm_router: &Arc<WasmChannelRouter>,
118	) -> (String, Box<dyn crate::channels::Channel>) {
119	    let channel_name = loaded.name().to_string();
120	    tracing::debug!("Loaded WASM channel: {}", channel_name);
121	    let owner_actor_id = config
122	        .channels
123	        .wasm_channel_owner_ids
124	        .get(channel_name.as_str())
125	        .map(ToString::to_string);
126	
127	    let secret_name = loaded.webhook_secret_name();
128	    let sig_key_secret_name = loaded.signature_key_secret_name();
129	    let hmac_secret_name = loaded.hmac_secret_name();
130	
131	    let webhook_secret = if let Some(secrets) = secrets_store {
132	        secrets
133	            .get_decrypted(&config.owner_id, &secret_name)
134	            .await
135	            .ok()
136	            .map(|s| s.expose().to_string())
137	    } else {
138	        None
139	    };
140	
141	    let secret_header = loaded.webhook_secret_header().map(|s| s.to_string());
142	
143	    let webhook_path = format!("/webhook/{}", channel_name);
144	    let endpoints = vec![RegisteredEndpoint {
145	        channel_name: channel_name.clone(),
146	        path: webhook_path,
147	        methods: vec!["POST".to_string()],
148	        require_secret: webhook_secret.is_some(),
149	    }];
150	
151	    let channel_arc = Arc::new(loaded.channel.with_owner_actor_id(owner_actor_id.clone()));
152	
153	    // Inject runtime config (tunnel URL, webhook secret, owner_id).
154	    {
155	        let mut config_updates = std::collections::HashMap::new();
156	
157	        if let Some(ref tunnel_url) = config.tunnel.public_url {
158	            config_updates.insert(
159	                "tunnel_url".to_string(),
160	                serde_json::Value::String(tunnel_url.clone()),
161	            );
162	        }
163	
164	        if let Some(ref secret) = webhook_secret {
165	            config_updates.insert(
166	                "webhook_secret".to_string(),
167	                serde_json::Value::String(secret.clone()),
168	            );
169	        }
170	
171	        if let Some(&owner_id) = config
172	            .channels
173	            .wasm_channel_owner_ids
174	            .get(channel_name.as_str())
175	        {
176	            config_updates.insert("owner_id".to_string(), serde_json::json!(owner_id));
177	        }
178	
179	        if channel_name == TELEGRAM_CHANNEL_NAME
180	            && let Some(store) = settings_store
181	            && let Ok(Some(serde_json::Value::String(username))) = store
182	                .get_setting("default", &bot_username_setting_key(&channel_name))
183	                .await
184	            && !username.trim().is_empty()
185	        {
186	            config_updates.insert("bot_username".to_string(), serde_json::json!(username));
187	        }
188	
189	        config_updates.extend(
190	            load_channel_setup_field_overrides(
191	                settings_store,
192	                &config.owner_id,
193	                &channel_name,
194	                loaded.capabilities_file.as_ref(),
195	            )
196	            .await,
197	        );
198	        // Inject channel-specific secrets into config for channels that need
199	        // credentials in API request bodies (e.g., Feishu token exchange).
200	        // The credential injection system only replaces placeholders in URLs
201	        // and headers, so channels like Feishu that exchange app_id + app_secret
202	        // for a tenant token need the raw values in their config.
203	        inject_channel_secrets_into_config(
204	            &channel_name,
205	            secrets_store,
206	            &config.owner_id,
207	            &mut config_updates,
208	        )
209	        .await;
210	
211	        if !config_updates.is_empty() {
212	            channel_arc.update_config(config_updates).await;
213	            tracing::info!(
214	                channel = %channel_name,
215	                has_tunnel = config.tunnel.public_url.is_some(),
216	                has_webhook_secret = webhook_secret.is_some(),
217	                "Injected runtime config into channel"
218	            );
219	        }
220	    }
221	
222	    tracing::info!(
223	        channel = %channel_name,
224	        has_webhook_secret = webhook_secret.is_some(),
225	        secret_header = ?secret_header,
226	        "Registering channel with router"
227	    );
228	
229	    wasm_router
230	        .register(
231	            Arc::clone(&channel_arc),
232	            endpoints,
233	            webhook_secret.clone(),
234	            secret_header,
235	        )
236	        .await;
237	
238	    // Register Ed25519 signature key if declared in capabilities.
239	    if let Some(ref sig_key_name) = sig_key_secret_name
240	        && let Some(secrets) = secrets_store
241	        && let Ok(key_secret) = secrets.get_decrypted(&config.owner_id, sig_key_name).await
242	    {
243	        match wasm_router
244	            .register_signature_key(&channel_name, key_secret.expose())
245	            .await
246	        {
247	            Ok(()) => {
248	                tracing::info!(channel = %channel_name, "Registered Ed25519 signature key")
249	            }
250	            Err(e) => {
251	                tracing::error!(channel = %channel_name, error = %e, "Invalid signature key in secrets store")
252	            }
253	        }
254	    }
255	
256	    // Register HMAC signing secret if declared in capabilities.
257	    if let Some(ref hmac_secret_name) = hmac_secret_name
258	        && let Some(secrets) = secrets_store
259	        && let Ok(secret) = secrets
260	            .get_decrypted(&config.owner_id, hmac_secret_name)
261	            .await
262	    {
263	        wasm_router
264	            .register_hmac_secret(&channel_name, secret.expose())
265	            .await;
266	        tracing::info!(channel = %channel_name, "Registered HMAC signing secret");
267	    }
268	
269	    // Inject credentials from secrets store / environment.
270	    match inject_channel_credentials(
271	        &channel_arc,
272	        secrets_store
273	            .as_ref()
274	            .map(|s| s.as_ref() as &dyn SecretsStore),
275	        &channel_name,
276	        &config.owner_id,
277	    )
278	    .await
279	    {
280	        Ok(count) => {
281	            if count > 0 {
282	                tracing::info!(
283	                    channel = %channel_name,
284	                    credentials_injected = count,
285	                    "Channel credentials injected"
286	                );
287	            }
288	        }
289	        Err(e) => {
290	            tracing::error!(
291	                channel = %channel_name,
292	                error = %e,
293	                "Failed to inject channel credentials"
294	            );
295	        }
296	    }
297	
298	    (channel_name, Box::new(SharedWasmChannel::new(channel_arc)))
299	}
