19	/// Known channel names and their crate names (for locating build artifacts).
20	const KNOWN_CHANNELS: &[(&str, &str)] = &[
21	    ("darkirc", "darkirc_channel"),
22	    ("discord", "discord_channel"),
23	    ("feishu", "feishu_channel"),
24	    ("slack", "slack_channel"),
25	    ("telegram", "telegram_channel"),
26	    ("weechat", "weechat_relay_channel"),
27	    ("whatsapp", "whatsapp_channel"),
28	    ("xmpp", "xmpp_channel"),
29	];
