36	/// Resolve the channels source directory.
37	///
38	/// Checks (in order):
39	/// 1. `IRONCLAW_CHANNELS_SRC` env var
40	/// 2. `<CARGO_MANIFEST_DIR>/channels-src/` (dev builds)
41	fn channels_src_dir() -> PathBuf {
42	    if let Ok(dir) = std::env::var("IRONCLAW_CHANNELS_SRC") {
43	        return PathBuf::from(dir);
44	    }
45	    PathBuf::from(CARGO_MANIFEST_DIR).join("channels-src")
46	}
