48	/// Locate the build artifacts for a channel.
49	///
50	/// Checks two layouts:
51	/// 1. **Flat** (Docker/packaged): `<channels_src>/<name>/<name>.wasm`
52	/// 2. **Build tree** (dev): `<channels_src>/<name>/target/wasm32-wasip2/release/<crate_name>.wasm`
53	///
54	/// Returns (wasm_path, capabilities_path) or an error if files are missing.
55	fn locate_channel_artifacts(name: &str) -> Result<(PathBuf, PathBuf), String> {
56	    let (_, crate_name) = KNOWN_CHANNELS
57	        .iter()
58	        .find(|(n, _)| *n == name)
59	        .ok_or_else(|| format!("Unknown channel '{}'", name))?;
60	
61	    let src_dir = channels_src_dir();
62	    let channel_dir = src_dir.join(name);
63	
64	    let caps_path = channel_dir.join(format!("{}.capabilities.json", name));
65	
66	    // Check flat layout first (Docker/packaged deployments)
67	    let flat_wasm = channel_dir.join(format!("{}.wasm", name));
68	    if flat_wasm.exists() && caps_path.exists() {
69	        return Ok((flat_wasm, caps_path));
70	    }
71	
72	    // Fall back to build tree layout (dev builds) — search across all WASM triples
73	    if let Some(build_wasm) =
74	        crate::registry::artifacts::find_wasm_artifact(&channel_dir, crate_name, "release")
75	        && caps_path.exists()
76	    {
77	        return Ok((build_wasm, caps_path));
78	    }
79	
80	    // Provide a helpful error with the paths we checked
81	    let expected_build = crate::registry::artifacts::resolve_target_dir(&channel_dir)
82	        .join("wasm32-wasip2/release")
83	        .join(format!("{}.wasm", crate_name));
84	
85	    Err(format!(
86	        "Channel '{}' WASM not found. Checked:\n  \
87	         - {} (flat/packaged)\n  \
88	         - {} (build tree, and other triples)\n  \
89	         Build it first:\n  \
90	         cd {} && cargo component build --release",
91	        name,
92	        flat_wasm.display(),
93	        expected_build.display(),
94	        channel_dir.display()
95	    ))
96	}
