98	/// Install a channel from build artifacts into the channels directory.
99	pub async fn install_bundled_channel(
100	    name: &str,
101	    target_dir: &Path,
102	    force: bool,
103	) -> Result<(), String> {
104	    let (wasm_src, caps_src) = locate_channel_artifacts(name)?;
105	
106	    fs::create_dir_all(target_dir)
107	        .await
108	        .map_err(|e| format!("Failed to create channels directory: {}", e))?;
109	
110	    let wasm_dst = target_dir.join(format!("{}.wasm", name));
111	    let caps_dst = target_dir.join(format!("{}.capabilities.json", name));
112	
113	    let has_existing = wasm_dst.exists() || caps_dst.exists();
114	    if has_existing && !force {
115	        return Err(format!(
116	            "Channel '{}' already exists at {}",
117	            name,
118	            target_dir.display()
119	        ));
120	    }
121	
122	    fs::copy(&wasm_src, &wasm_dst)
123	        .await
124	        .map_err(|e| format!("Failed to copy {}: {}", wasm_src.display(), e))?;
125	    fs::copy(&caps_src, &caps_dst)
126	        .await
127	        .map_err(|e| format!("Failed to copy {}: {}", caps_src.display(), e))?;
128	
129	    Ok(())
130	}
