132	/// Check which known channels have build artifacts available.
133	pub fn available_channel_names() -> Vec<&'static str> {
134	    KNOWN_CHANNELS
135	        .iter()
136	        .filter(|(name, _)| locate_channel_artifacts(name).is_ok())
137	        .map(|(name, _)| *name)
138	        .collect()
139	}
