3	//! Loads WASM channel modules from the filesystem (default: ~/.ironclaw/channels/).
4	//! Each channel consists of:
5	//! - `<name>.wasm` - The compiled WASM component
6	//! - `<name>.capabilities.json` - Channel capabilities and configuration
7	
8	use std::collections::HashMap;
