23	
24	/// Loads WASM channels from the filesystem.
25	pub struct WasmChannelLoader {
26	    runtime: Arc<WasmChannelRuntime>,
27	    pairing_store: Arc<PairingStore>,
28	    settings_store: Option<Arc<dyn SettingsStore>>,
29	    secrets_store: Option<Arc<dyn SecretsStore + Send + Sync>>,
30	    owner_scope_id: String,
31	}
32	
33	impl WasmChannelLoader {
34	    /// Create a new loader with the given runtime and pairing store.
35	    pub fn new(
36	        runtime: Arc<WasmChannelRuntime>,
37	        pairing_store: Arc<PairingStore>,
38	        settings_store: Option<Arc<dyn SettingsStore>>,
39	        owner_scope_id: impl Into<String>,
40	    ) -> Self {
41	        Self {
42	            runtime,
