44	            settings_store,
45	            secrets_store: None,
46	            owner_scope_id: owner_scope_id.into(),
47	        }
48	    }
49	
50	    /// Set the secrets store for host-based credential injection in WASM channels.
51	    pub fn with_secrets_store(mut self, store: Arc<dyn SecretsStore + Send + Sync>) -> Self {
52	        self.secrets_store = Some(store);
53	        self
54	    }
55	
56	    /// Load a single WASM channel from a file pair.
57	    ///
58	    /// Expects:
59	    /// - `wasm_path`: Path to the `.wasm` file
60	    /// - `capabilities_path`: Path to the `.capabilities.json` file (optional)
61	    ///
62	    /// If no capabilities file is provided, the channel gets minimal capabilities.
63	    pub async fn load_from_files(
64	        &self,
65	        name: &str,
66	        wasm_path: &Path,
67	        capabilities_path: Option<&Path>,
68	    ) -> Result<LoadedChannel, WasmChannelError> {
69	        // Validate name
70	        if name.is_empty() || name.contains('/') || name.contains('\\') || name.contains("..") {
71	            return Err(WasmChannelError::InvalidName(name.to_string()));
72	        }
73	
74	        // Read WASM bytes
75	        if !wasm_path.exists() {
76	            return Err(WasmChannelError::WasmNotFound(wasm_path.to_path_buf()));
77	        }
78	        let wasm_bytes = fs::read(wasm_path).await?;
79	
80	        // Read capabilities file
81	        let (capabilities, config_json, description, cap_file) =
82	            if let Some(cap_path) = capabilities_path {
83	                if cap_path.exists() {
84	                    let cap_bytes = fs::read(cap_path).await?;
85	                    let cap_file = ChannelCapabilitiesFile::from_bytes(&cap_bytes)
86	                        .map_err(|e| WasmChannelError::InvalidCapabilities(e.to_string()))?;
87	                    cap_file.validate();
88	
89	                    // Debug: log raw capabilities
90	                    tracing::debug!(
91	                        channel = name,
92	                        raw_capabilities = ?cap_file.capabilities,
93	                        "Parsed capabilities file"
94	                    );
95	
96	                    // Check WIT version compatibility
97	                    crate::tools::wasm::loader::check_wit_version_compat(
98	                        name,
99	                        cap_file.wit_version.as_deref(),
100	                        crate::tools::wasm::WIT_CHANNEL_VERSION,
101	                    )
102	                    .map_err(|e| WasmChannelError::IncompatibleWitVersion(e.to_string()))?;
103	
104	                    let caps = cap_file.to_capabilities();
105	
106	                    // Debug: log resulting capabilities
107	                    tracing::info!(
108	                        channel = name,
109	                        http_allowed = caps.tool_capabilities.http.is_some(),
110	                        http_allowlist_count = caps
111	                            .tool_capabilities
112	                            .http
113	                            .as_ref()
114	                            .map(|h| h.allowlist.len())
115	                            .unwrap_or(0),
