151	/// Build a WASM component using `cargo-component` (sync, for CLI use).
152	///
153	/// Returns the path to the built artifact.
154	pub fn build_wasm_component_sync(source_dir: &Path, release: bool) -> anyhow::Result<PathBuf> {
155	    use std::process::Command;
156	
157	    println!("Building WASM component in {}...", source_dir.display());
158	
159	    // Check if cargo-component is available
160	    let check = Command::new("cargo")
161	        .args(["component", "--version"])
162	        .output();
163	
164	    if check.is_err() || !check.as_ref().map(|o| o.status.success()).unwrap_or(false) {
165	        anyhow::bail!(
166	            "cargo-component not found. Install with: cargo install cargo-component\n\
167	             Or use --skip-build with an existing .wasm file."
168	        );
169	    }
170	
171	    let mut cmd = Command::new("cargo");
172	    cmd.current_dir(source_dir).args(["component", "build"]);
173	
174	    if release {
175	        cmd.arg("--release");
176	    }
177	
178	    println!(
179	        "  Running: cargo component build{}",
180	        if release { " --release" } else { "" }
181	    );
182	
183	    let output = cmd.output()?;
184	
185	    if !output.status.success() {
186	        let stderr = String::from_utf8_lossy(&output.stderr);
187	        anyhow::bail!("Build failed:\n{}", stderr);
188	    }
189	
190	    let profile = if release { "release" } else { "debug" };
191	
192	    // Find the built artifact
193	    find_any_wasm_artifact(source_dir, profile).ok_or_else(|| {
194	        anyhow::anyhow!(
195	            "No .wasm file found after build in {}/target/*/{}",
196	            source_dir.display(),
197	            profile,
198	        )
199	    })
200	}
201	
202	/// Copy WASM binary + optional `capabilities.json` sidecar to an install directory.
203	///
204	/// Looks for capabilities files in `source_dir` matching several naming conventions.
205	/// Returns the destination wasm path.
206	pub async fn install_wasm_files(
207	    wasm_src: &Path,
208	    source_dir: &Path,
209	    name: &str,
210	    target_dir: &Path,
211	    force: bool,
212	) -> anyhow::Result<PathBuf> {
213	    fs::create_dir_all(target_dir).await?;
214	
215	    let wasm_dst = target_dir.join(format!("{}.wasm", name));
216	    let caps_dst = target_dir.join(format!("{}.capabilities.json", name));
217	
218	    if wasm_dst.exists() && !force {
219	        anyhow::bail!(
220	            "Tool '{}' already exists at {}. Use --force to overwrite.",
221	            name,
222	            wasm_dst.display()
223	        );
224	    }
225	
226	    // Copy WASM binary
227	    fs::copy(wasm_src, &wasm_dst).await?;
228	
229	    // Look for capabilities.json sidecar in the source directory
230	    let caps_candidates = [
231	        source_dir.join(format!("{}.capabilities.json", name)),
232	        source_dir.join(format!("{}-tool.capabilities.json", name)),
233	        source_dir.join("capabilities.json"),
234	    ];
235	    for caps_src in &caps_candidates {
236	        if caps_src.exists() {
237	            if let Err(e) = fs::copy(caps_src, &caps_dst).await {
238	                tracing::warn!(
239	                    "Failed to copy capabilities sidecar {} -> {}: {}",
240	                    caps_src.display(),
241	                    caps_dst.display(),
242	                    e,
243	                );
244	            }
245	            break;
246	        }
247	    }
248	
249	    Ok(wasm_dst)
250	}
